const airportByCode = (code) => AIRPORTS.find((a) => a.code === code);
const airportLabel = (code) => {
  const a = airportByCode(code);
  return a ? `${a.city} (${a.code})` : code;
};

// Strategy per region-pair. Each strategy is a function of (originHub, destHub)
// that returns the leg structure + note. Only pairs that need a WORKAROUND are
// listed — pairs with good direct cabin routes are handled by DIRECT_ROUTES.
// Where a pair genuinely has no cabin path at all, it's deliberately omitted
// and the planner shows the honest "no mapped route" message.
//
// VERIFIED FACTS THESE STRATEGIES REST ON (official sources, May 2026):
// - No airline flies cabin pets INTO the UK (UK govt rule) — must use a
//   European hub + Eurotunnel/ferry land crossing.
// - Ireland is NOT the UK: cabin pets CAN fly in (Iberia Madrid→Dublin,
//   KLM Amsterdam→Dublin), but direct cabin options are limited.
// - Cabin OUT of the UK/Ireland to Europe IS allowed (Air France, KLM, Lufthansa).
// - Etihad: cabin OUT of Abu Dhabi to Europe allowed; cabin INTO the UAE blocked
//   on "flights to" the UAE — Dubai (DXB) is cargo-only for all airlines.
// - Air India: cargo-only to/from the UK (LHR/LGW only — no pet service from BHX);
//   no service of any kind to/from USA, Canada or Australia; cabin allowed
//   DEPARTING the UAE (UAE→India only — reverse direction blocked); Ultra
//   Long Haul flights have no cabin pets even when otherwise eligible.
// - Transatlantic cabin works between European hubs and major US cities
//   (Air France, KLM, Lufthansa, Delta, etc.).

// Resolve a SPECIFIC leg flight time from the maintained EU_HUB_OPTIONS.routeTimes
// table when the origin is a single known city, else fall back to the band.
// Used by REGION_PAIR_STRATEGIES so a hub leg like "Miami (MIA) → Paris (CDG)"
// shows the concrete "9h 55m" instead of a generic "7–11h" band — keeping these
// hand-written strategy cards consistent with the planner's generated via-hub
// cards (single source of truth = EU_HUB_OPTIONS.routeTimes). The band stays the
// honest display whenever the origin is multi-city/generic or the pair is
// uncatalogued. `originLabel` is like "Miami (MIA)"; `hubCode` is "CDG"/"FRA"/etc.
function legTime(originLabel, hubCode, fallbackBand) {
  const m = (originLabel || "").match(/\(([A-Z]{3})\)/);
  const originCode = m ? m[1] : null;
  if (!originCode) return fallbackBand; // generic/multi-origin → band is honest
  const hub = (typeof EU_HUB_OPTIONS !== "undefined")
    ? EU_HUB_OPTIONS.find((h) => h.code === hubCode)
    : null;
  const specific = hub && hub.routeTimes ? hub.routeTimes[originCode] : null;
  return specific || fallbackBand; // uncatalogued pair → band is honest
}

// Resolve the time for a "Hub → ${d}" leg where the hub is one OR several options
// (e.g. "Paris (CDG) or Amsterdam (AMS)"). Reads each candidate hub's
// EU_HUB_OPTIONS.routeTimes[destCode] (same single source of truth as legTime)
// and returns: the single concrete time when only one hub serves the pair; a
// TIGHT band built from the real per-hub values (min–max) when several do; or the
// honest fallback band when the destination isn't catalogued for any of them.
// This stops the bug where a multi-hub leg showed a wide generic band (e.g.
// "7–11h") whose floor was LOWER than either hub's real time to that city (CDG→MIA
// 8h 55m, AMS→MIA 9h 40m). `hubCodes` is an array like ["CDG","AMS"]; `destLabel`
// is like "Miami (MIA)". Parses to total-minutes to sort/compare, re-renders the
// extremes verbatim from the table so the displayed strings stay authoritative.
function hubLegTime(hubCodes, destLabel, fallbackBand) {
  const m = (destLabel || "").match(/\(([A-Z]{3})\)/);
  const destCode = m ? m[1] : null;
  if (!destCode || typeof EU_HUB_OPTIONS === "undefined") return fallbackBand;
  const times = [];
  for (const code of hubCodes) {
    const hub = EU_HUB_OPTIONS.find((h) => h.code === code);
    const t = hub && hub.routeTimes ? hub.routeTimes[destCode] : null;
    if (t) times.push(t);
  }
  if (times.length === 0) return fallbackBand; // no catalogued hub→dest → band honest
  if (times.length === 1) return times[0];     // single known time
  const toMin = (s) => {
    const h = /(\d+)\s*h/.exec(s);
    const min = /(\d+)\s*m/.exec(s);
    return (h ? +h[1] : 0) * 60 + (min ? +min[1] : 0);
  };
  const sorted = times.slice().sort((a, b) => toMin(a) - toMin(b));
  const lo = sorted[0], hi = sorted[sorted.length - 1];
  return lo === hi ? lo : `${lo}–${hi}`; // tight band from REAL extremes
}

// ── DIRECT_LEG_TIMES — master origin→destination nonstop-leg time table ──────
// Many strategy legs are "${o} → ${d}" or "Hub → ${d}" where the endpoints are
// specific airports (oLabel/dLabel carry IATA codes, e.g. "Mexico City (MEX)").
// A single flat band per region understated or overstated real legs (e.g. the
// old via-Canada "2–4h" showed for YUL→SFO which is really ~6h 15m). This table
// holds VERIFIED nonstop durations keyed ORIGINCODE→DESTCODE, and legPairTime()
// resolves a leg to its concrete time when the pair is catalogued, else returns
// the honest band. Pairs with NO nonstop service are deliberately absent → band
// (an honest "varies" rather than a fabricated number). Same principle as
// legTime() (which stays for the transatlantic EU-hub table).
//
// Verification log (chat 17+): fill region by region. A pair present here has
// been checked against Tier-1 route data (airline schedules / flightconnections).
//   ✓ Canada origins (YUL, YYZ) → US — fully swept.
//   … Mexico, Central/South America, Caribbean, India, Japan, Korea — in progress.
const DIRECT_LEG_TIMES = {
  // ----- Canada hubs → US (verified chat 17) -----
  YUL: {
    JFK: "1h 45m", BOS: "1h 30m", PIT: "1h 40m", IAD: "1h 55m",
    ORD: "2h 35m", DFW: "3h 45m", MIA: "3h 50m", IAH: "4h 30m",
    AUS: "4h 35m", SEA: "5h 55m", LAX: "6h", SFO: "6h 15m",
    // EWR, BWI, SLC, CLT: no nonstop from YUL → band (honest).
  },
  YYZ: {
    PIT: "1h 20m", IAD: "1h 30m", JFK: "1h 45m", EWR: "1h 45m",
    BOS: "1h 45m", ORD: "2h", CLT: "2h 5m", IAH: "3h 20m",
    AUS: "3h 35m", DFW: "3h 35m", MIA: "3h 50m", SLC: "4h 30m",
    SEA: "5h 30m", LAX: "5h 30m", SFO: "5h 40m",
    // BWI: no nonstop from YYZ (connection-only) → band (honest).
  },
  // ----- Mexico City (MEX) → US (verified chat 17) -----
  MEX: {
    IAH: "2h 24m", DFW: "2h 43m", AUS: "3h", MIA: "3h 43m",
    LAX: "3h 49m", CLT: "4h", SLC: "4h 25m", SFO: "4h 30m",
    IAD: "4h 30m", ORD: "4h 30m", JFK: "4h 39m", BOS: "5h 20m",
    SEA: "5h 30m",
    // EWR, BWI, PIT: no nonstop from MEX → band (honest).
  },
  // ----- Cancún (CUN) → US (verified chat 17; major cabin-corridor pairs) -----
  // CUN nonstop-serves ~all offered US cities (leisure megahub). Major pairs
  // verified below; long-tail (BWI, AUS, PIT, SLC, SFO, SEA, BOS, IAD) still
  // resolve to the honest band until individually checked.
  CUN: {
    MIA: "2h", IAH: "2h 5m", CLT: "2h 40m", DFW: "2h 45m",
    ORD: "3h 45m", JFK: "4h 10m", EWR: "4h 10m", LAX: "4h 45m",
  },
  // ----- Guadalajara (GDL) → US (verified chat 17; concrete-time pairs) -----
  // GDL nonstop-serves LAX, ORD, IAH, DFW, SFO, MIA, CLT, SLC, SEA, EWR (mostly
  // Volaris/Aeromexico). Concrete times below; MIA/CLT/SLC/SEA/EWR resolve to
  // the honest band until individually timed. No nonstop: JFK, BOS, IAD, BWI,
  // AUS, PIT → band.
  GDL: {
    IAH: "2h 20m", DFW: "2h 40m", LAX: "3h", ORD: "4h", SFO: "4h 20m",
  },
  // ----- Caribbean origins → US (verified chat 17; main MIA/JFK corridors) -----
  // The Caribbean "1–4h" band is already accurate for most island→US gateways;
  // concrete times added for the dominant Miami and JFK corridors. Uncatalogued
  // island→city pairs fall back to the honest band.
  MBJ: { MIA: "2h", JFK: "4h" },              // Montego Bay, Jamaica
  SDQ: { MIA: "2h 25m" },                       // Santo Domingo, DR
  PUJ: { MIA: "2h 40m" },                       // Punta Cana, DR
  // NAS (Nassau) → MIA is a ~1h hop, well within the band → left to band.
  // ----- South America origins → US (verified chat 17; Avianca BOG corridor) -----
  BOG: { MIA: "3h 50m", JFK: "5h 50m" },        // Bogotá (Avianca direct US gateways)
};
// Resolve "${originLabel} → ${destLabel}" to a concrete nonstop time when the
// pair is catalogued in DIRECT_LEG_TIMES; else return the honest fallback band.
// Either label may be generic (no IATA code) — then the band is the honest show.
function legPairTime(originLabel, destLabel, fallbackBand) {
  const om = (originLabel || "").match(/\(([A-Z]{3})\)/);
  const dm = (destLabel || "").match(/\(([A-Z]{3})\)/);
  const o = om ? om[1] : null;
  const d = dm ? dm[1] : null;
  if (!o || !d) return fallbackBand; // generic endpoint → band is honest
  const row = DIRECT_LEG_TIMES[o];
  const specific = row ? row[d] : null;
  return specific || fallbackBand; // uncatalogued pair → band is honest
}
// Back-compat shim: the via-Canada leg passes a hub code + dest label. Express
// it through the general table so there is one source of truth.
function viaCanadaOnwardTime(canadaCode, destLabel, fallbackBand) {
  const dm = (destLabel || "").match(/\(([A-Z]{3})\)/);
  const d = dm ? dm[1] : null;
  if (!d) return fallbackBand;
  const row = DIRECT_LEG_TIMES[canadaCode];
  return (row && row[d]) || fallbackBand;
}

